query:
query FindMinimalMetadata {
  minimalMetadata {
    objectMetadataItems {
      id
      nameSingular
      namePlural
      labelSingular
      labelPlural
      icon
      isActive
      isSystem
      isRemote
      __typename
    }
    views {
      id
      type
      key
      objectMetadataId
      __typename
    }
    collectionHashes {
      collectionName
      hash
      __typename
    }
    __typename
  }
}
